/**
 * 传输玩家到支持 NetherNet 连接的目标服务器时所使用的选项。
 *
 * Options when transferring a player to a server that supports
 * NetherNet connections.
 */
export interface TransferPlayerNetherNetOptions {
    /**
     * @remarks
     * 目标服务器的 NetherNet ID。
     *
     * NetherNet ID of the destination server.
     *
     */
    netherNetId: string;
}
